//! Reading an omega tape: the protobuf types, and the replay of a tape into
//! fidget shapes (`decode`). See render's tape.rs for the format and the
//! writer; this half needs nothing native, so the browser build (../wasm)
//! shares it with render.

pub mod cellular;
pub mod level_set;
pub mod noise;
pub mod spinodoid;

// Generated by prost-build from common/tape/tape.proto (see build.rs).
pub mod tape_proto {
    include!(concat!(env!("OUT_DIR"), "/tape.rs"));
}

use fidget_core::context::{Context, Tree};
use fidget_core::shape::ShapeVars;
use fidget_core::var::Var;
use fidget_core::vm::VmShape;

/// A replayed tape: the whole-scene field (the min of the outputs), each
/// output alone, as a shape and as the tree it was built from (for a caller
/// that composes the outputs some other way), their names, the defaults of
/// its inputs, and the scene box the tape recorded, if any ([xmin, ymin,
/// zmin, xmax, ymax, zmax]).
pub struct Decoded {
    pub combined: VmShape,
    pub outputs: Vec<VmShape>,
    pub output_trees: Vec<Tree>,
    pub names: Vec<String>,
    pub shape_vars: ShapeVars<f32>,
    pub bbox: Option<[f32; 6]>,
    /// Each output's colour and material trees, parallel to `outputs`, when
    /// the tape carries them (its `appearance`); empty otherwise.
    pub appearance: Vec<Appearance>,
}

/// One output's colour and material fields, as trees.
pub struct Appearance {
    /// sRGB [r, g, b].
    pub color: Option<[Tree; 3]>,
    /// The material record, rows flattened (see tape.proto's Appearance).
    pub material: Option<[Tree; 12]>,
    /// The material's displacement is not a constant zero.
    pub displaced: bool,
}

fn child(nodes: &[Tree], idx: u32) -> Result<Tree, String> {
    nodes
        .get(idx as usize)
        .cloned()
        .ok_or_else(|| format!("node reference {} out of range", idx))
}

fn apply_unary(op: i32, a: Tree) -> Result<Tree, String> {
    use tape_proto::UnaryOp as U;
    let u = U::try_from(op).map_err(|_| format!("unknown unary op {}", op))?;
    Ok(match u {
        U::Neg => a.neg(),
        U::Abs => a.abs(),
        U::Recip => a.recip(),
        U::Sqrt => a.sqrt(),
        U::Square => a.square(),
        U::Floor => a.floor(),
        U::Ceil => a.ceil(),
        U::Round => a.round(),
        U::Sin => a.sin(),
        U::Cos => a.cos(),
        U::Tan => a.tan(),
        U::Asin => a.asin(),
        U::Acos => a.acos(),
        U::Atan => a.atan(),
        U::Exp => a.exp(),
        U::Ln => a.ln(),
        U::Not => a.not(),
    })
}

fn apply_binary(op: i32, l: Tree, r: Tree) -> Result<Tree, String> {
    use tape_proto::BinaryOp as B;
    let b = B::try_from(op).map_err(|_| format!("unknown binary op {}", op))?;
    Ok(match b {
        B::Add => l + r,
        B::Sub => l - r,
        B::Mul => l * r,
        B::Div => l / r,
        B::Atan2 => l.atan2(r),
        B::Min => l.min(r),
        B::Max => l.max(r),
        B::Compare => l.compare(r),
        B::Mod => l.modulo(r),
        B::And => l.and(r),
        B::Or => l.or(r),
    })
}

/// One mesh-oracle id a tape references, and what it denotes.
pub struct OracleUse {
    /// The leaf id, as `Tree::mesh_oracle` carries it.
    pub id: u32,
    /// "noise", "cellular", "spinodoid", "hodgeSpinodoid", "mesh" (a payload
    /// the tape carries) or "unknown".
    pub kind: &'static str,
    /// True when [`decode`] resolves this id by itself — a library-baked tile,
    /// or a source mesh the tape carries. False means the caller must register
    /// the oracle before loading, because the tape does not describe it.
    pub self_contained: bool,
    /// The table slot to register against, for the kinds that have one
    /// (spinodoid). Several leaf ids share a slot: one per component.
    pub slot: Option<u32>,
}

/// Every mesh-oracle id the tape's nodes reference, deduplicated in
/// first-appearance order, with what each one denotes.
///
/// A tape binds oracles by id, and an id alone is not a description: a
/// spinodoid leaf names a baked kernel table that the tape has no field for.
/// So a caller replaying a tape in a process that did not build it has to ask
/// what to register *before* calling [`decode`], which is where the bindings
/// are consumed. `self_contained == false` is that list.
pub fn oracle_uses(tape: &tape_proto::Tape) -> Vec<OracleUse> {
    use tape_proto::node::N;

    let mut out: Vec<OracleUse> = Vec::new();
    for node in &tape.nodes {
        let Some(N::MeshOracle(id)) = &node.n else {
            continue;
        };
        if out.iter().any(|u| u.id == *id) {
            continue;
        }
        // A vdbSdf leaf carries the high bit; its payload is stored under the
        // bare asset id, so mask it off before matching the tape's oracles.
        let bare = *id & !VDB_ASSET_BIT;
        let (kind, self_contained, slot) = if crate::noise::noise_channel_of_id(*id).is_some() {
            ("noise", true, None)
        } else if crate::cellular::leaf_of_id(*id).is_some() {
            ("cellular", true, None)
        } else if let Some((slot, _)) = crate::spinodoid::hodge::leaf_of_id(*id) {
            ("hodgeSpinodoid", false, Some(slot))
        } else if let Some((slot, _)) = crate::spinodoid::leaf_of_id(*id) {
            ("spinodoid", false, Some(slot))
        } else if tape.oracles.iter().any(|o| o.asset_id == bare) {
            ("mesh", true, None)
        } else {
            ("unknown", false, None)
        };
        out.push(OracleUse {
            id: *id,
            kind,
            self_contained,
            slot,
        });
    }
    out
}

/// The bit a vdbSdf leaf id carries above its payload's asset id. Kept here
/// rather than reached for from render, so the browser build can classify a
/// leaf without the native oracle crates; it must agree with render's
/// `vdb_oracle::VDB_ASSET_BIT`.
const VDB_ASSET_BIT: u32 = 0x8000_0000;

pub fn decode(
    tape: &tape_proto::Tape,
    register_oracle: &mut dyn FnMut(&tape_proto::OraclePayload) -> Result<(), String>,
) -> Result<Decoded, String> {
    use tape_proto::node::N;

    // Register embedded oracle payloads so MeshOracle leaves resolve in this
    // process — the tape carries the source mesh, and the caller's hook
    // chooses what to build from it (render: an exact BVH or a VDB level set).
    for (i, o) in tape.oracles.iter().enumerate() {
        if tape_proto::OracleKind::try_from(o.kind).is_err() {
            return Err(format!("oracle {}: unknown kind {}", i, o.kind));
        }
        register_oracle(o).map_err(|e| format!("oracle {}: {}", i, e))?;
    }

    // Noise-tile oracle: the tile is library-baked, so a noise leaf carries only
    // its id. Register the channel oracle for every noise leaf the tape
    // references, so `Tree::mesh_oracle(noise_id)` resolves on replay.
    for node in &tape.nodes {
        if let Some(N::MeshOracle(id)) = &node.n {
            if let Some((ch, octaves)) = crate::noise::noise_channel_of_id(*id) {
                crate::noise::register_channel(ch, octaves)
                    .map_err(|e| format!("noise channel {}: {}", ch, e))?;
            }
            // Cellular oracle leaves, likewise: the tile is library-baked, so
            // the leaf carries only its id, which names the component and the
            // octave count.
            if let Some((comp, octaves)) = crate::cellular::leaf_of_id(*id) {
                crate::cellular::register(comp, octaves)
                    .map_err(|e| format!("cellular component {}: {}", comp, e))?;
            }
        }
    }

    let mut nodes: Vec<Tree> = Vec::with_capacity(tape.nodes.len());
    let mut shape_vars = ShapeVars::<f32>::new();

    for (i, node) in tape.nodes.iter().enumerate() {
        let n = node
            .n
            .as_ref()
            .ok_or_else(|| format!("node {} has no payload", i))?;
        let tree = match n {
            N::Axis(a) => match tape_proto::Axis::try_from(*a) {
                Ok(tape_proto::Axis::X) => Tree::x(),
                Ok(tape_proto::Axis::Y) => Tree::y(),
                Ok(tape_proto::Axis::Z) => Tree::z(),
                Err(_) => return Err(format!("node {}: unknown axis {}", i, a)),
            },
            N::Constant(c) => Tree::constant(*c as f32),
            N::Input(input) => {
                let var = Var::new();
                if let Some(vi) = var.index() {
                    shape_vars.insert(vi, input.default as f32);
                }
                Tree::from(var)
            }
            N::Unary(u) => apply_unary(u.op, child(&nodes, u.arg)?)?,
            N::Binary(b) => apply_binary(b.op, child(&nodes, b.lhs)?, child(&nodes, b.rhs)?)?,
            N::MeshOracle(id) => {
                // Keep Var::X/Y/Z in the tape's variable map even for a bare
                // oracle leaf — mirrors the tree_mesh_oracle FFI. The
                // (v - v) triplet folds to zero but isn't constant-folded away
                // (neither operand is a constant), so without it slice/interval
                // eval and meshing feed the oracle degenerate coordinates.
                let (ax, ay, az) = Tree::axes();
                Tree::mesh_oracle(*id)
                    + ((ax.clone() - ax) + (ay.clone() - ay) + (az.clone() - az))
            }
            N::Remap(rm) => {
                let target = child(&nodes, rm.target)?;
                target.remap_xyz(child(&nodes, rm.x)?, child(&nodes, rm.y)?, child(&nodes, rm.z)?)
            }
        };
        nodes.push(tree);
    }

    if tape.outputs.is_empty() {
        return Err("tape has no outputs".into());
    }

    // One Tree per output, plus their `min` (the whole-scene field, matching
    // the mesh path's `fidget.Min`).
    let mut output_trees: Vec<Tree> = Vec::with_capacity(tape.outputs.len());
    for &o in &tape.outputs {
        output_trees.push(child(&nodes, o)?);
    }
    let mut combined_tree = output_trees[0].clone();
    for t in &output_trees[1..] {
        combined_tree = combined_tree.min(t.clone());
    }

    let to_shape = |tree: &Tree| -> Result<VmShape, String> {
        let mut ctx = Context::new();
        let node = ctx.import(tree);
        VmShape::new(&ctx, node).map_err(|e| format!("VmShape::new failed: {:?}", e))
    };
    let combined = to_shape(&combined_tree)?;
    let mut outputs = Vec::with_capacity(output_trees.len());
    for t in &output_trees {
        outputs.push(to_shape(t)?);
    }

    let mut appearance = Vec::with_capacity(tape.appearance.len());
    for a in &tape.appearance {
        let channels = |ids: &[u32]| -> Result<Vec<Tree>, String> { ids.iter().map(|&i| child(&nodes, i)).collect() };
        let color = match a.color.len() {
            0 => None,
            3 => channels(&a.color)?.try_into().ok(),
            n => return Err(format!("appearance colour has {} channels, not 3", n)),
        };
        let material = match a.material.len() {
            0 => None,
            12 => channels(&a.material)?.try_into().ok(),
            n => return Err(format!("appearance material has {} entries, not 12", n)),
        };
        appearance.push(Appearance { color, material, displaced: a.displaced });
    }

    // Names parallel to outputs, padded/truncated so indexing is always safe.
    let mut names = tape.output_names.clone();
    names.resize(outputs.len(), String::new());

    let bbox = if tape.bbox.len() == 6 {
        Some([
            tape.bbox[0],
            tape.bbox[1],
            tape.bbox[2],
            tape.bbox[3],
            tape.bbox[4],
            tape.bbox[5],
        ])
    } else {
        None
    };

    Ok(Decoded {
        combined,
        outputs,
        output_trees,
        names,
        appearance,
        shape_vars,
        bbox,
    })
}

